 address(r1,0,'10.10.10.1','255.255.255.0','2001:db8:10::1','fe80::1','BRANCH_LAN');address(r1,1,'192.0.2.1','255.255.255.252','2001:db8:12::1','fe80::1','TO_ISP1');
 address(isp,1,'192.0.2.2','255.255.255.252','2001:db8:12::2','fe80::2','TO_R1');address(isp,0,'203.0.113.1','255.255.255.0','2001:db8:20::1','fe80::2','SERVER_LAN');
 isp.config.interfaces.Loopback0={...defaultInterface('Loopback0'),adminUp:true,ip:'198.51.100.1',mask:'255.255.255.255',ipv6:['2001:db8:100::1/128'],description:'ADDITIONAL_REMOTE_TARGET'};
