 for(const sw of [asw,dsw]){const p=sw.config.interfaces[g(24)];Object.assign(p,{mode:'trunk',nativeVlan:99,allowedVlans:[10,99],description:'TRUSTED_UPLINK'});Object.assign(p.features,{nonegotiate:true,portfast:false,bpduguard:false});}
