 Object.assign(r.config.interfaces['GigabitEthernet0/0'],{ip:'192.168.10.254',mask:'255.255.255.0',adminUp:true,description:'TO_SW1'});
 const networkPorts:[Device,string][]=[[r,'GigabitEthernet0/0'],[sw1,'GigabitEthernet0/1'],[sw1,'GigabitEthernet0/24'],[sw2,'GigabitEthernet0/24']];
