 const switches=[make('DSW1','l3switch',300,160),make('DSW2','l3switch',800,160)],pcs=[make('PC1','pc',300,430),make('PC2','pc',800,430)];
 for(const[i,sw]of switches.entries()){const subnet=i===0?10:20,p=sw.config.interfaces['GigabitEthernet0/1'];Object.assign(p,{switchport:false,ip:`192.168.${subnet}.1`,mask:'255.255.255.0',description:'TO_PC'+(i+1)});sw.config.ipRouting=false;for(const n of [23,24])sw.config.interfaces[`GigabitEthernet0/${n}`].adminUp=false;const host=pcs[i].config.interfaces.GigabitEthernet0;Object.assign(host,{ip:`192.168.${subnet}.10`,mask:'255.255.255.0'});host.features.dhcp=false;pcs[i].config.defaultGateway=`192.168.${subnet}.1`;}
